-- 업무 일지는 Batch 메타데이터 보관 정책과 독립적으로 중복 생성을 방지한다.
CREATE TABLE report_batch_runs (
    run_key VARCHAR(100) NOT NULL PRIMARY KEY,
    target_month CHAR(7) NOT NULL,
    kind VARCHAR(10) NOT NULL,
    status VARCHAR(20) NOT NULL DEFAULT 'READY',
    targets_fixed BOOLEAN NOT NULL DEFAULT FALSE,
    created_count INT NOT NULL DEFAULT 0,
    skipped_count INT NOT NULL DEFAULT 0,
    execution_id BIGINT NULL,
    created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6)
) ENGINE=InnoDB;
CREATE TABLE report_batch_months (
    target_month CHAR(7) NOT NULL PRIMARY KEY,
    owner_run_key VARCHAR(100) NULL
) ENGINE=InnoDB;
CREATE TABLE report_batch_targets (
    run_key VARCHAR(100) NOT NULL,
    user_id BIGINT NOT NULL,
    state VARCHAR(12) NOT NULL DEFAULT 'NEW',
    callback_status VARCHAR(12) NULL,
    callback_fingerprint CHAR(64) NULL,
    PRIMARY KEY(run_key,user_id),
    CONSTRAINT fk_report_target_run FOREIGN KEY(run_key) REFERENCES report_batch_runs(run_key)
) ENGINE=InnoDB;
CREATE TABLE report_ai_dispatches (
    batch_request_id CHAR(36) NOT NULL PRIMARY KEY,
    run_key VARCHAR(100) NOT NULL,
    state VARCHAR(20) NOT NULL DEFAULT 'PREPARED',
    sent_at DATETIME(6) NULL,
    confirmed_by VARCHAR(100) NULL,
    confirmation_note VARCHAR(500) NULL,
    confirmed_at DATETIME(6) NULL,
    CONSTRAINT uk_report_dispatch_run UNIQUE(run_key),
    CONSTRAINT fk_report_dispatch_run FOREIGN KEY(run_key) REFERENCES report_batch_runs(run_key)
) ENGINE=InnoDB;

-- 운영자가 종료를 확인한 실행의 복구 근거는 자동 정리하지 않는다.
CREATE TABLE report_batch_recoveries (
    recovery_id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,
    execution_id BIGINT NULL,
    CONSTRAINT uk_report_recovery_execution_id UNIQUE(execution_id),
    run_key VARCHAR(100) NOT NULL,
    actor VARCHAR(100) NOT NULL,
    evidence VARCHAR(500) NOT NULL,
    confirmed_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    CONSTRAINT fk_report_recovery_run FOREIGN KEY(run_key) REFERENCES report_batch_runs(run_key)
) ENGINE=InnoDB;

-- 다음 미처리 대상 조회와 예약 대상 복원은 실행·상태·사용자 순서를 사용한다.
CREATE INDEX idx_report_targets_run_state_user
    ON report_batch_targets(run_key, state, user_id);
